import{_ as t,o as a,c as l,a4 as r}from"./chunks/framework.cM03Lg2X.js";const b=JSON.parse('{"title":"计算、通信与云原生","description":"AI 计算集群、RDMA 集合通信、分布式存储与 Kubernetes 调度的关键结论。","frontmatter":{"title":"计算、通信与云原生","description":"AI 计算集群、RDMA 集合通信、分布式存储与 Kubernetes 调度的关键结论。"},"headers":[],"relativePath":"ai-infra/compute-network.md","filePath":"ai-infra/compute-network.md","lastUpdated":1786332289000}'),i={name:"ai-infra/compute-network.md"};function o(n,e,d,h,p,c){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="计算、通信与云原生" tabindex="-1">计算、通信与云原生 <a class="header-anchor" href="#计算、通信与云原生" aria-label="Permalink to “计算、通信与云原生”">​</a></h1><p>大模型集群的有效算力取决于最慢的那条链路。算力、通信、存储、供电散热和作业调度彼此耦合，万卡规模下任何局部不稳定都会被放大为整体效率损失。</p><h2 id="计算集群-从芯片指标到有效算力" tabindex="-1">计算集群：从芯片指标到有效算力 <a class="header-anchor" href="#计算集群-从芯片指标到有效算力" aria-label="Permalink to “计算集群：从芯片指标到有效算力”">​</a></h2><p>AI 服务器与传统通用服务器的差异，核心在于加速器密度、高速互连、内存带宽和供电散热。集群规模继续扩大后，关注点会从单卡峰值算力转向：</p><ul><li>网络是否能支撑高频集合通信；</li><li>故障是否能被快速定位、隔离与恢复；</li><li>训练显存是否为参数、梯度、优化器状态和激活预留了真实空间；</li><li>MFU 是否反映了通信、气泡和不均衡后的有效利用率。</li></ul><p>万卡集群的主要挑战可以归为五类：电力与散热、网络通信、计算效率、系统可靠性、国产化与成本。规模越大，平均故障间隔越短，“无故障运行”不再现实，故障感知与弹性恢复必须进入训练系统设计。</p><h2 id="通信-并行策略最终都会落到通信原语" tabindex="-1">通信：并行策略最终都会落到通信原语 <a class="header-anchor" href="#通信-并行策略最终都会落到通信原语" aria-label="Permalink to “通信：并行策略最终都会落到通信原语”">​</a></h2><table tabindex="0"><thead><tr><th>并行方式</th><th>典型通信</th><th>主要压力</th></tr></thead><tbody><tr><td>数据并行</td><td>AllReduce / ReduceScatter + AllGather</td><td>梯度同步带宽</td></tr><tr><td>张量并行</td><td>AllReduce / AllGather</td><td>层内高频通信与低延迟</td></tr><tr><td>流水线并行</td><td>Send / Recv</td><td>阶段间激活传输与气泡</td></tr><tr><td>专家并行</td><td>AllToAll</td><td>流量不均与尾延迟</td></tr></tbody></table><p>RDMA 绕过传统内核网络栈并减少数据拷贝，是大规模训练网络的基础。RoCEv2 在以太网上提供 RDMA，但要结合 PFC、ECN/DCQCN、合理拓扑与负载均衡处理拥塞；仅开启“无损”并不能自动消除 PFC 风暴、死锁和大象流问题。</p><p>NCCL / HCCL 等集合通信库负责把逻辑原语映射到实际互连拓扑。优化时应先确认 Scale-Up 与 Scale-Out 边界，再决定 Ring、Tree、分层集合通信或拓扑感知调度。</p><h2 id="存储-checkpoint-是训练稳定性的组成部分" tabindex="-1">存储：Checkpoint 是训练稳定性的组成部分 <a class="header-anchor" href="#存储-checkpoint-是训练稳定性的组成部分" aria-label="Permalink to “存储：Checkpoint 是训练稳定性的组成部分”">​</a></h2><p>Checkpoint 不只是备份文件。大模型训练中的保存、恢复和跨节点传输会占用大量带宽与停顿时间，需要在以下方案间权衡：</p><ul><li>分片保存，避免集中写入；</li><li>异步或增量 Checkpoint，降低训练停顿；</li><li>计算节点本地缓存与并行文件系统配合；</li><li>明确模型状态、优化器状态与数据游标的完整性边界。</li></ul><p>分布式文件系统的设计目标并非只有峰值吞吐，还包括元数据扩展、故障恢复、小文件行为与训练访问模式适配。</p><h2 id="云原生-容器是隔离视图-kubernetes-是控制循环" tabindex="-1">云原生：容器是隔离视图，Kubernetes 是控制循环 <a class="header-anchor" href="#云原生-容器是隔离视图-kubernetes-是控制循环" aria-label="Permalink to “云原生：容器是隔离视图，Kubernetes 是控制循环”">​</a></h2><p>容器的本质是 Namespace 提供资源视图隔离、Cgroups 提供资源限制、OverlayFS 组织镜像层；它并不是轻量虚拟机。Kubernetes 在此基础上通过声明式 API 和控制器持续把实际状态拉回期望状态。</p><p>在 AI 集群中，重点不是“会写 Deployment”，而是：</p><ol><li>用 requests / limits 和 QoS 明确资源边界；</li><li>让 GPU、拓扑、存储和网络约束进入调度；</li><li>使用 CSI、CNI、CRI 分离存储、网络和运行时实现；</li><li>用 Prometheus、日志与告警覆盖从节点到作业的三层指标；</li><li>为长任务设计优先级、抢占、失败恢复与可观测性。</li></ol><h2 id="使用这组知识时先问" tabindex="-1">使用这组知识时先问 <a class="header-anchor" href="#使用这组知识时先问" aria-label="Permalink to “使用这组知识时先问”">​</a></h2><ul><li>当前瓶颈是单节点算力、跨卡互连还是跨节点网络？</li><li>性能数据测的是峰值、端到端吞吐，还是故障后的长期均值？</li><li>存储与调度策略是否匹配训练任务的持续时间和恢复成本？</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/01-AI-33b3a54bd6b481ca9c04cc173faa7102" target="_blank" rel="noreferrer">Notion：01 AI 计算集群</a></li><li><a href="https://app.notion.com/p/02-33b3a54bd6b481d0be5be686660e9c82" target="_blank" rel="noreferrer">Notion：02 通信与存储</a></li><li><a href="https://app.notion.com/p/03-33b3a54bd6b48108bbfdfae21b318b4a" target="_blank" rel="noreferrer">Notion：03 集群容器与云原生</a></li></ul><blockquote><p>限制：原 Notion 总结明确标注了部分上游章节仍是占位内容。本页只保留已有正文能支持的系统框架，不把占位标题扩写为事实。</p></blockquote>',23)])])}const u=t(i,[["render",o]]);export{b as __pageData,u as default};
